'use strict';
(()=>{
const $=id=>document.getElementById(id),menu=$('main-menu'),intro=$('intro-cinema'),video=$('intro-video'),film=document.querySelector('.intro-film'),fallback=film?.querySelector?.('.intro-fallback'),status=$('menu-status'),saveModal=$('overwrite-save-modal'),saveStatus=$('overwrite-save-status'),exportSave=$('export-save');
if(!menu)return;
const introSlot=menu.querySelector('.menu-video-slot');if(introSlot)introSlot.innerHTML='<span>PRÓLOGO CINEMÁTICO · PIXEL-ART</span><b>Cuando las campanas callan</b><small>Una secuencia unificada narra la carta, la Vigilia y el Umbral antes de crear a tu personaje.</small>';
const introCopy=document.querySelector('.intro-copy');if(introCopy)introCopy.innerHTML='<span class="menu-kicker">PRÓLOGO CINEMÁTICO · VALDARA</span><h2 id="intro-title">La carta sellada</h2><p>La premisa completa vive dentro de la secuencia: las campanas, la carta de ceniza y el Umbral que vuelve a responder.</p><button id="skip-intro" class="menu-secondary" type="button">Continuar al creador</button>';
function hasSave(){try{const bridge=window.CenizasBridge;if(bridge?.hasSave)return bridge.hasSave();const c=JSON.parse(localStorage.getItem('cenizas-character-v1')||'null'),p=JSON.parse(localStorage.getItem('cenizas-valdara-v1')||'null');return Boolean(c?.name?.trim()&&c.race&&c.class&&c.subclass&&c.gender&&p&&Number.isInteger(p.stage));}catch{return false}}
function hasAnySave(){try{const bridge=window.CenizasBridge;if(bridge?.hasAnySave)return bridge.hasAnySave();if(window.CenizasSaveProtection?.hasAny)return window.CenizasSaveProtection.hasAny();return ['cenizas-valdara-v1','cenizas-character-v1','cenizas-campaign-v2'].some(key=>localStorage.getItem(key)!==null)}catch{return false}}
function refresh(){const button=$('continue-game'),saved=hasSave();button.disabled=!saved;button.setAttribute('aria-disabled',String(!saved));if(!saved)status.textContent='No hay una partida guardada todavía.';else status.textContent='Partida encontrada en este dispositivo.';}
function closeMenu(){menu.dataset.active='false';menu.setAttribute('aria-hidden','true');}
function showIntro(done){let finished=false;const finish=()=>{if(finished)return;finished=true;clearTimeout(timer);video.onended=null;video.onerror=null;video.pause?.();intro.hidden=true;intro.setAttribute('aria-hidden','true');intro.dataset.stage='closed';film.hidden=false;intro.style.gridTemplateRows='';introCopy.style.alignSelf='';introCopy.style.padding='';film.classList.remove('video-ready');if(fallback){fallback.style.opacity='';fallback.style.pointerEvents='';}window.CenizasMusic?.set('exploration');done();};const timer=setTimeout(finish,60000);intro.hidden=false;intro.setAttribute('aria-hidden','false');intro.dataset.stage='video';film.hidden=false;intro.style.gridTemplateRows='';introCopy.style.alignSelf='';introCopy.style.padding='';film.classList.remove('video-ready');if(fallback){fallback.style.opacity='';fallback.style.pointerEvents='';}video.currentTime=0;video.load?.();const ready=()=>{film.classList.add('video-ready');if(fallback){fallback.style.opacity='0';fallback.style.pointerEvents='none';}};video.onloadeddata=ready;video.oncanplay=ready;video.onerror=()=>{film.classList.remove('video-ready');if(fallback){fallback.style.opacity='';fallback.style.pointerEvents='';}};video.onended=finish;video.play().catch(()=>{});window.CenizasMusic?.enable?.();window.CenizasMusic?.set('intro');const skip=$('skip-intro');if(skip)skip.onclick=finish;}
function openOverwrite(){if(!saveModal?.showModal){status.textContent='Hay una partida guardada. Confirma desde un navegador compatible para empezar otra.';return;}if(saveStatus)saveStatus.textContent='';saveModal.returnValue='';saveModal.showModal();}
function startConfirmed(){closeMenu();showIntro(()=>{const result=window.CenizasBridge?.startNew?.({confirmed:true});if(result?.ok===false){menu.dataset.active='true';menu.setAttribute('aria-hidden','false');status.textContent='No se pudo crear el respaldo. Tu partida anterior sigue intacta.';refresh();}});}
function newGame(){if(hasAnySave()){openOverwrite();return;}closeMenu();showIntro(()=>window.CenizasBridge?.startNew?.({confirmed:true}));}
function continueGame(){closeMenu();window.CenizasBridge?.continueGame?.();}
$('new-game').onclick=newGame;$('continue-game').onclick=continueGame;$('exit-game').onclick=()=>{status.textContent='Puedes cerrar esta pestaña cuando quieras. Tu progreso guardado permanecerá en este dispositivo.';try{window.close();}catch{/* optional storage/API unavailable; safe fallback */}};
if(saveModal?.addEventListener){saveModal.addEventListener('close',()=>{const action=saveModal.returnValue;saveModal.returnValue='';if(action==='confirm')startConfirmed();});}
if(exportSave)exportSave.onclick=()=>{const protection=window.CenizasSaveProtection,backup=protection?.snapshot?.();if(backup&&protection.download?.(backup)){if(saveStatus)saveStatus.textContent='Respaldo descargado. Aún no se ha reemplazado tu partida.';}else if(saveStatus)saveStatus.textContent='No se pudo descargar el respaldo; puedes cancelar sin perder nada.';};
refresh();window.CenizasMenu={refresh,showIntro,openOverwrite};window.addEventListener('storage',refresh);window.addEventListener('pageshow',refresh);
})();
